import io
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def extract_receipt_fields(payload, config=None):
    config = config or {}
    with DocumentIntelligenceClient(config['endpoint'], AzureKeyCredential(config['api_key'])) as client:
        result = client.begin_analyze_document('prebuilt-receipt',
            body=io.BytesIO(payload['document_bytes']), content_type=payload['mime_type']).result()
    receipts = []
    for document in result.documents or []:
        fields = document.fields or {}
        text = lambda values, key: values[key].content if key in values else None
        items = fields.get('Items')
        lines = []
        for item in (items.value_array or []) if items else []:
            values = item.value_object or {}
            lines.append({'description': text(values, 'Description'), 'quantity': text(values, 'Quantity'),
                           'amount': text(values, 'Amount')}) 
        receipts.append({'merchant': text(fields, 'MerchantName'), 'tax': text(fields, 'Tax'),
                          'total': text(fields, 'Total'), 'items': lines})
    return {'receipts': receipts}

import json


def normalize_expense(expense_data):
    normalized_expense = {
        'vendor': expense_data.get('vendor', ''),
        'date': expense_data.get('date', ''),
        'total': expense_data.get('total', ''),
        'line_items': expense_data.get('line_items', [])
    }
    return json.dumps(normalized_expense, indent=2)

def validate_document_fields(document_fields):
    required_fields = ['vendor', 'date', 'total', 'line_items']
    missing_fields = [field for field in required_fields if field not in document_fields]
    if missing_fields:
        raise ValueError(f'Missing required fields: {missing_fields}')
    for item in document_fields.get('line_items', []):
        if not all(key in item for key in ['description', 'quantity', 'amount']):
            raise ValueError('Line items must contain description, quantity, and amount fields')
    return True

class DocumentRequest:
    def __init__(self, document_bytes, mime_type):
        self.document_bytes = document_bytes
        self.mime_type = mime_type


class DocumentResponse:
    def __init__(self, documents):
        self.documents = documents


class NormalizedExpense:
    def __init__(self, vendor, date, total, line_items):
        self.vendor = vendor
        self.date = date
        self.total = total
        self.line_items = line_items

def summarize_invoice_fields(invoice_fields):
    summary = {
        'vendor': invoice_fields['vendor'],
        'date': invoice_fields['date'],
        'total': invoice_fields['total'],
        'line_items_count': len(invoice_fields['line_items'])
    }
    return summary
